def _joint_segment(self, qa, qb, v_max=V_MAX, min_s=0.6):
        dq = float(np.abs(qb - qa).max())
        T = max(min_s, np.pi / 2 * dq / v_max)
        n = max(1, int(np.ceil(T * FPS)))
        return qa + _hc(n)[:, None] * (qb - qa)
